return ['domain'=>'woocommerce-multilingual','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'WPML Multilingual & Multicurrency for WooCommerce 5.6.0','pot-creation-date'=>'2026-09-12T13:36:01+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Multilingual & Multicurrency for WooCommerce'=>'WPML Multilingual & Multicurrency for WooCommerce','https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml','Make your store multilingual and enable multiple currencies | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">Documentation</a>'=>'اجعل متجرك متعدد اللغات وفعّل العملات المتعددة | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">الوثائق</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Language of the content to read.'=>'لغة المحتوى المطلوب قراءته.','Currency for the returned prices.'=>'العملة للأسعار المرجعة.','WPML Multilingual & Multicurrency for WooCommerce detected an active cache plugin on your site.'=>'اكتشف WPML Multilingual & Multicurrency for WooCommerce وجود إضافة ذاكرة كاش نشطة على موقعك.','Caching may cause currency display issues for your customers if you are using the multicurrency feature.'=>'قد تتسبب ذاكرة الكاش في مشكلات في عرض العملة لعملائك إذا كنت تستخدم ميزة العملات المتعددة.','To avoid this, set your cache plugin to not cache pages for visitors that have a cookie set in their browser.'=>'لتجنب ذلك، اضبط إضافة ذاكرة الكاش لديك بحيث لا تقوم بتخزين الصفحات للزوار الذين لديهم ملف تعريف ارتباط (cookie) في متصفحهم.','Important: Action Needed for Your <b>Currency Switcher</b>'=>'هام: إجراء مطلوب بخصوص <b>مبدل العملات</b> الخاص بك','We detected that your site is using a <b>Currency Switcher</b> built with Twig templates. For security reasons, support for Twig-based templates will be discontinued in the upcoming version of WPML Multilingual & Multicurrency for WooCommerce 5.6.'=>'لقد اكتشفنا أن موقعك يستخدم <b>مبدل عملات</b> تم بناؤه باستخدام قوالب Twig. لأسباب أمنية، سيتم إيقاف دعم القوالب القائمة على Twig في الإصدار القادم من WPML Multilingual & Multicurrency for WooCommerce 5.6.','To ensure your <b>Currency Switcher</b> continues working smoothly:'=>'لضمان استمرار عمل <b>مبدل العملات</b> الخاص بك بسلاسة:','- Switch to a PHP-based template - you can select one from the %1$sconfiguration page%2$s.'=>'- انتقل إلى قالب قائم على PHP - يمكنك اختيار واحد من %1$sصفحة الإعدادات%2$s.','- Need a custom solution? %1$sContact our support%2$s - we’re here to help you migrate safely.'=>'- هل تحتاج إلى حل مخصص؟ %1$sاتصل بالدعم الفني لدينا%2$s - نحن هنا لمساعدتك في الهجرة بأمان.','We recommend updating your <b>Currency Switcher</b> as soon as possible to avoid disruptions when the new version of WPML Multilingual & Multicurrency for WooCommerce is released.'=>'نوصي بتحديث <b>مبدل العملات</b> الخاص بك في أقرب وقت ممكن لتجنب أي انقطاع عند إصدار النسخة الجديدة من WPML Multilingual & Multicurrency for WooCommerce.','Migrating your multilingual shop? With %s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'هل تقوم بترحيل متجرك متعدد اللغات؟ باستخدام %s يمكنك نقل محتواك المترجم إلى موقع جديد، بما في ذلك عروض البيع المتقاطع، وعروض البيع البديل، وسمات المنتج.','Looking to import your multilingual shop? With %1$s and %2$s in both your original and new site, you can export and import your translations automatically.'=>'هل تتطلع إلى استيراد متجرك متعدد اللغات؟ باستخدام %1$s و %2$s في كل من موقعك الأصلي والجديد، يمكنك تصدير واستيراد ترجماتك تلقائيًا.','WPML Export and Import'=>'WPML Export and Import','You haven\'t added any secondary currencies'=>'لم تقم بإضافة أي عملات ثانوية','Please add another currency to fully utilize multicurrency mode. If you do not need multiple currencies, you can disable this setting to improve your site\'s performance.'=>'يرجى إضافة عملة أخرى للاستفادة الكاملة من وضع العملات المتعددة. إذا لم تكن بحاجة إلى عملات متعددة، يمكنك تعطيل هذا الإعداد لتحسين أداء موقعك.','Configure multicurrency mode'=>'تكوين وضع العملات المتعددة','Review WPML Multilingual & Multicurrency for WooCommerce'=>'مراجعة WPML Multilingual & Multicurrency for WooCommerce','Congrats on making your first multicurrency sale!'=>'تهانينا على إتمام أول عملية بيع بعملات متعددة!','Want to help <strong>WPML Multilingual & Multicurrency for WooCommerce</strong> plugin? %1$sGive us a review%2$s!'=>'هل تريد مساعدة إضافة <strong>WPML Multilingual & Multicurrency for WooCommerce</strong>؟ %1$sأعطنا تقييمًا%2$s!','Currency - no orders found'=>'العملة - لم يتم العثور على طلبات','Invalid nonce'=>'رمز تحقق غير صالح','WPML synced translations for product-level changes only.'=>'قام WPML بمزامنة الترجمات للتغييرات على مستوى المنتج فقط.','WPML synced translations for %1$d of %2$d variations.'=>'قام WPML بمزامنة الترجمات لـ %1$d من أصل %2$d من التنويعات.','%d other variation was not checked because its data didn\'t change here.'=>'لم يتم التحقق من %d تنويعات أخرى لأن بياناتها لم تتغير هنا.' . "\0" . 'لم يتم التحقق من تنويع آخر %d لأن بياناته لم تتغير هنا.' . "\0" . 'لم يتم التحقق من تنويعين آخرين %d لأن بياناتهما لم تتغير هنا.' . "\0" . 'لم يتم التحقق من %d تنويعًا آخر لأن بياناتها لم تتغير هنا.' . "\0" . 'لم يتم التحقق من %d تنويعًا آخر لأن بياناتها لم تتغير هنا.' . "\0" . 'لم يتم التحقق من %d تنويع آخر لأن بياناتها لم تتغير هنا.','If you\'ve made changes <strong>outside this editor</strong> (for example, retranslating an attribute term), use <em>%s</em> below to make sure every translation is current.'=>'إذا قمت بإجراء تغييرات <strong>خارج هذا المحرر</strong> (على سبيل المثال، إعادة ترجمة مصطلح سمة)، فاستخدم <em>%s</em> أدناه للتأكد من أن كل ترجمة محدثة.','Force update all'=>'فرض تحديث الكل','Force update all variation translations'=>'فرض تحديث جميع ترجمات التنويعات','You can switch to <em>"Always check all variations"</em> on the %s.'=>'يمكنك التبديل إلى <em>”التحقق دائمًا من جميع التنويعات“</em> في %s.','WCML Settings page'=>'صفحة إعدادات WCML','(opens in a new tab)'=>'(يفتح في علامة تبويب جديدة)','Syncing all variations…'=>'جاري مزامنة جميع التنويعات…','Done — all variations synced'=>'تم — تمت مزامنة جميع التنويعات','Sync completed for product #%d.'=>'اكتملت المزامنة للمنتج رقم %d.','Failed — see console'=>'فشل — راجع وحدة التحكم (console)','Error — '=>'خطأ — ','Dismiss'=>'تجاهل','WPML verified %1$d variation × %2$d language on this save. None of them had changes that needed syncing.'=>'تحقق WPML من %1$d تنويعات × %2$d لغات عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.' . "\0" . 'تحقق WPML من تنويع واحد %1$d × لغة واحدة %2$d عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.' . "\0" . 'تحقق WPML من تنويعين %1$d × لغتين %2$d عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.' . "\0" . 'تحقق WPML من %1$d تنويعًا × %2$d لغة عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.' . "\0" . 'تحقق WPML من %1$d تنويعًا × %2$d لغة عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.' . "\0" . 'تحقق WPML من %1$d تنويع × %2$d لغة عند هذا الحفظ. لم يكن لأي منها تغييرات تحتاج إلى مزامنة.','That\'s wasted work. Switching to <em>"Only sync variations edited in the editor"</em> would make saves like this much faster — WPML will only sync the variations you actually changed and tell you what was skipped.'=>'هذا عمل ضائع. التبديل إلى <em>”مزامنة التنويعات التي تم تعديلها في المحرر فقط“</em> سيجعل عمليات الحفظ مثل هذه أسرع بكثير — سيقوم WPML فقط بمزامنة التنويعات التي قمت بتغييرها بالفعل ويخبرك بما تم تخطيه.','You can switch on the %s.'=>'يمكنك التبديل في %s.','Don\'t show this again on this site'=>'لا تظهر هذا مجددًا على هذا الموقع','Variation translation sync on product save'=>'مزامنة ترجمة التنويعات عند حفظ المنتج','Choose how WPML updates variation translations when you save a variable product. Affects saves in the WooCommerce product editor only — Translation Dashboard and Translate Everything Automatically always run a complete sync.'=>'اختر كيف يقوم WPML بتحديث ترجمات التنويعات عند حفظ منتج متنوع. يؤثر هذا على عمليات الحفظ في محرر منتجات WooCommerce فقط — بينما تقوم لوحة إدارة الترجمة وترجم كل شيء تلقائيًا دائمًا بتشغيل مزامنة كاملة.','Choose how WPML updates variation translations when you save a variable product.'=>'اختر كيف يقوم WPML بتحديث ترجمات التنويعات عند حفظ منتج متنوع.','Affects saves in the WooCommerce product editor only. <b>Translation Dashboard</b> and <b>Translate Everything</b> Automatically always run a complete sync.'=>'يؤثر فقط على عمليات الحفظ في محرر منتجات WooCommerce. تقوم <b>لوحة إدارة الترجمة</b> و<b>ترجم كل شيء</b> تلقائيًا دائمًا بتشغيل مزامنة كاملة.','Always check all variations'=>'التحقق دائمًا من جميع التنويعات','On every save, WPML checks every variation in every language and syncs anything that\'s out of date.'=>'عند كل عملية حفظ، يتحقق WPML من كل تنويع في كل لغة ويزامن أي شيء قديم.','Only sync variations edited in the editor'=>'مزامنة التنويعات التي تم تعديلها في المحرر فقط','WPML syncs only the variations changed in this save. After each save, WPML shows what was synced and offers a one-click full sync.'=>'يقوم WPML بمزامنة التنويعات التي تم تغييرها في عملية الحفظ هذه فقط. بعد كل عملية حفظ، يعرض WPML ما تمت مزامنته ويقدم خيار المزامنة الكاملة بنقرة واحدة.','To translate custom WooCommerce email notifications, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة إشعارات بريد WooCommerce الإلكتروني المخصصة، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','Monthly on the %s'=>'شهريًا في %s','Weekly on %s'=>'أسبوعيًا في يوم %s','Cannot get exchange rates. Connection failed.'=>'تعذر الحصول على أسعار الصرف. فشل الاتصال.','Please note that the payment will be made in %1$s. Your total will be approximately %2$s, depending on the current exchange rate.'=>'يرجى ملاحظة أن الدفع سيتم بـ %1$s. سيكون إجمالي المبلغ تقريبًا %2$s، اعتمادًا على سعر الصرف الحالي.','Not yet supported'=>'غير مدعوم بعد','Set the currency in which your customer will see the final price when they checkout. Choose which accounts they will see in their payment message.'=>'حدد العملة التي سيرى بها عميلك السعر النهائي عند إتمام الطلب. اختر الحسابات التي سيراها في رسالة الدفع الخاصة به.','Currency'=>'العملة','Bank Account'=>'الحساب البنكي','All Accounts'=>'جميع الحسابات','All in selected currency'=>'الكل بالعملة المختارة','PayPal Email'=>'بريد PayPal الإلكتروني','Merchant ID'=>'معرف التاجر','Client ID'=>'معرف العميل','Secret Key'=>'المفتاح السري','This gateway does not support %s. To show this gateway please select another currency.'=>'هذه البوابة لا تدعم %s. لعرض هذه البوابة، يرجى اختيار عملة أخرى.','WPML could not read this payment from PayPal, so no refund was sent. Please try the refund again.'=>'تعذر على WPML قراءة هذه الدفعة من PayPal، لذا لم يتم إرسال أي استرداد للأموال. يرجى محاولة استرداد الأموال مرة أخرى.','The refund amount is too small to send to PayPal in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'مبلغ استرداد الأموال صغير جدًا بحيث لا يمكن إرساله إلى PayPal بعملة الدفع، لذا لم يتم إرسال أي استرداد للأموال. استرد مبلغًا أكبر، أو سجّل استرداد الأموال يدويًا في WooCommerce.','WPML could not work out how much to refund on this order, so no refund was sent. Check the exchange rate for the order\'s currency in WPML\'s multicurrency settings, then try the refund again.'=>'تعذر على WPML تحديد المبلغ المطلوب استرداده لهذا الطلب، لذا لم يتم إرسال أي استرداد للأموال. تحقق من سعر الصرف لعملة الطلب في إعدادات تعدد العملات في WPML، ثم حاول استرداد الأموال مرة أخرى.','Live Publishable Key'=>'مفتاح النشر المباشر (Live)','Live Secret Key'=>'المفتاح السري المباشر (Live)','Test Publishable Key'=>'مفتاح النشر التجريبي (Test)','Test Secret Key'=>'المفتاح السري التجريبي (Test)','Connect with Stripe'=>'الاتصال بـ Stripe','Connect a test account'=>'توصيل حساب تجريبي','Reconnect with Stripe'=>'إعادة الاتصال بـ Stripe','Reconnect the test account'=>'إعادة توصيل الحساب التجريبي','Connected with Stripe'=>'متصل بـ Stripe','You will continue on Stripe. Save your changes first. Anything unsaved on this screen is lost.'=>'ستنتقل للمتابعة على Stripe. احفظ تغييراتك أولاً. سيتم فقدان أي شيء غير محفوظ في هذه الشاشة.','Stripe could not be connected. Please try again.'=>'تعذر الاتصال بـ Stripe. يرجى المحاولة مرة أخرى.','This payment is already refunded in full on Stripe, so no refund was sent. Record the refund manually in WooCommerce instead.'=>'تم استرداد هذه الدفعة بالكامل بالفعل على Stripe، لذا لم يتم إرسال أي استرداد للأموال. سجّل استرداد الأموال يدويًا في WooCommerce بدلاً من ذلك.','The refund amount is too small to send to Stripe in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'مبلغ استرداد الأموال صغير جدًا بحيث لا يمكن إرساله إلى Stripe بعملة الدفع، لذا لم يتم إرسال أي استرداد للأموال. استرد مبلغًا أكبر، أو سجّل استرداد الأموال يدويًا في WooCommerce.','WPML could not read this payment from Stripe, so no refund was sent. Please try the refund again.'=>'تعذر على WPML قراءة هذه الدفعة من Stripe، لذا لم يتم إرسال أي استرداد للأموال. يرجى محاولة استرداد الأموال مرة أخرى.','PayPal took this payment in %1$s, and WooCommerce can only send a refund in %2$s. Refund this order in your PayPal account, then record it here with "Refund manually".'=>'استلم PayPal هذه الدفعة بـ %1$s، ولا يمكن لـ WooCommerce إرسال استرداد للأموال إلا بـ %2$s. استرد أموال هذا الطلب في حسابك على PayPal، ثم سجله هنا باستخدام ”استرداد يدوي“.','Language'=>'اللغة','Costs and values in custom currencies'=>'التكاليف والقيم بالعملات المخصصة','WPML Multilingual & Multicurrency for WooCommerce by default will multiply all your costs and values defined above by currency exchange rates. If you don\'t want this and you prefer static values instead, you can define them here.'=>'سيقوم WPML Multilingual & Multicurrency for WooCommerce افتراضيًا بضرب جميع تكاليفك وقيمك المحددة أعلاه بأسعار صرف العملات. إذا كنت لا تريد ذلك وتفضل القيم الثابتة بدلاً من ذلك، يمكنك تحديدها هنا.','Enable costs in custom currencies'=>'تمكين التكاليف بالعملات المخصصة','Calculate shipping costs in other currencies automatically'=>'حساب تكاليف الشحن بالعملات الأخرى تلقائيًا','Set shipping costs in other currencies manually'=>'تعيين تكاليف الشحن بالعملات الأخرى يدويًا','The label for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.Minimal order amount in %s'=>'الحد الأدنى لمبلغ الطلب بـ %s','The description for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.The minimal order amount if customer choose %s as a purchase currency.'=>'الحد الأدنى لمبلغ الطلب إذا اختار العميل %s كعملة شراء.','Your shipping class %1$s has been created in %2$s language. Please switch your language if you want to provide shipping costs in different currencies for this class.'=>'تم إنشاء فئة الشحن %1$s الخاصة بك باللغة %2$s. يرجى تبديل لغتك إذا كنت ترغب في تقديم تكاليف الشحن بعملات مختلفة لهذه الفئة.','"%1$s" shipping class cost in %2$s'=>'تكلفة فئة الشحن ”%1$s“ بـ %2$s','N/A'=>'غير متاح','No shipping class cost in %s'=>'لا توجد تكلفة لفئة الشحن بـ %s','The label for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.Cost in %s'=>'التكلفة بـ %s','The description for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.The shipping cost if customer choose %s as a purchase currency.'=>'تكلفة الشحن إذا اختار العميل %s كعملة شراء.','Your site needs HTTPS to connect a live Stripe account. You can still connect a test account.'=>'يحتاج موقعك إلى بروتوكول HTTPS لتوصيل حساب Stripe حقيقي. لا يزال بإمكانك توصيل حساب تجريبي.','Stripe did not return a connection link. Please try again.'=>'لم يقم Stripe بإرجاع رابط اتصال. يرجى المحاولة مرة أخرى.','Stripe is now connected for %s.'=>'تم توصيل Stripe الآن لـ %s.','Stripe could not be connected for %s. Please try again.'=>'تعذر توصيل Stripe لـ %s. يرجى المحاولة مرة أخرى.','Currencies'=>'العملات','Add currency'=>'إضافة عملة','Rate'=>'سعر الصرف','default'=>'افتراضي','Edit'=>'تعديل','Currency displayed first'=>'العملة المعروضة أولاً','Choose which currency to display when a client switches languages'=>'اختر العملة التي سيتم عرضها عندما يقوم العميل بتبديل اللغات','Keep'=>'إبقاء','Delete'=>'حذف','Currencies to display for each language'=>'العملات المراد عرضها لكل لغة','Add a secondary currency to choose which currencies appear for each language.'=>'أضف عملة ثانوية لاختيار العملات التي تظهر لكل لغة.','Enable %1$s for %2$s'=>'تمكين %1$s لـ %2$s','Disable %1$s for %2$s'=>'تعطيل %1$s لـ %2$s','Settings'=>'إعدادات','Add new currency'=>'إضافة عملة جديدة','Currency settings for %s'=>'إعدادات العملة لـ %s','Select currency'=>'اختر العملة','Exchange Rate'=>'سعر الصرف','Only numeric'=>'رقمي فقط','(previous value: %s)'=>'(القيمة السابقة: %s)','Currency Preview'=>'معاينة العملة','Currency Position'=>'موضع العملة','Left'=>'يسار','Right'=>'يمين','Left with space'=>'يسار مع مسافة','Right with space'=>'يمين مع مسافة','Thousand Separator'=>'فاصل الآلاف','(Space)'=>'(مسافة)','Decimal Separator'=>'الفاصل العشري','Number of Decimals'=>'عدد العشريات','Rounding to the nearest integer'=>'التقريب إلى أقرب عدد صحيح','Disabled'=>'معطل','Up'=>'للأعلى','Down'=>'للأسفل','Nearest'=>'الأقرب','Increment for nearest integer'=>'زيادة لأقرب عدد صحيح','The resulting price will be an increment of this value after initial rounding.%se.g.:'=>'سيكون السعر الناتج زيادة لهذه القيمة بعد التقريب الأولي.%sعلى سبيل المثال:','1454.07 &raquo; 1454 when set to 1'=>'1454.07 &laquo; 1454 عند الضبط على 1','1454.07 &raquo; 1450 when set to 10'=>'1454.07 &laquo; 1450 عند الضبط على 10','1454.07 &raquo; 1500 when set to 100'=>'1454.07 &laquo; 1500 عند الضبط على 100','Round the converted price to the closest integer. %se.g. 15.78 becomes 16.00'=>'تقريب السعر المحول إلى أقرب عدد صحيح. %sعلى سبيل المثال 15.78 يصبح 16.00','The value to be subtracted from the amount obtained previously.'=>'القيمة التي سيتم طرحها من المبلغ الذي تم الحصول عليه سابقًا.','For 1454.07, when the increment for the nearest integer is 100 and the auto-subtract amount is 1, the resulting amount is 1499.'=>'بالنسبة لـ 1454.07، عندما تكون الزيادة لأقرب عدد صحيح هي 100 ومبلغ الطرح التلقائي هو 1، يكون المبلغ الناتج هو 1499.','Autosubtract amount'=>'مبلغ الطرح التلقائي','Payment Gateways'=>'بوابات الدفع','Custom settings for %s'=>'إعدادات مخصصة لـ %s','Learn more'=>'معرفة المزيد','Please enter a valid number'=>'يرجى إدخال رقم صالح','The currency was not saved. Try again.'=>'لم يتم حفظ العملة. حاول مرة أخرى.','The setting was not saved. Try again.'=>'لم يتم حفظ الإعداد. حاول مرة أخرى.','Cancel'=>'إلغاء','Save'=>'حفظ','Currency available in'=>'العملة متاحة في','All countries'=>'جميع الدول','All countries except: '=>'جميع الدول باستثناء: ','All countries except...'=>'جميع الدول باستثناء...','Specific countries'=>'دول محددة','Show currencies based on'=>'عرض العملات بناءً على','You need the WPML plugin to make your store multilingual and display currencies based on site language. Don\'t have it yet?'=>'أنت بحاجة إلى إضافة WPML لجعل متجرك متعدد اللغات وعرض العملات بناءً على لغة الموقع. ألا تملكها بعد؟','Purchase WPML now'=>'اشترِ WPML الآن','Site Language'=>'لغة الموقع','Client Location'=>'موقع العميل','Location based'=>'بناءً على الموقع','WooCommerce integrates with MaxMind Geolocation to reliably determine the location of your customers.'=>'يتكامل WooCommerce مع MaxMind Geolocation لتحديد موقع عملائك بشكل موثوق.','Great! Now you can use Geolocation to determine default currency for chosen languages. You can edit that key in '=>'رائع! الآن يمكنك استخدام الموقع الجغرافي (Geolocation) لتحديد العملة الافتراضية للغات المختارة. يمكنك تعديل هذا المفتاح في ','WooCommerce settings page.'=>'صفحة إعدادات WooCommerce.','MaxMind Licence Key'=>'مفتاح ترخيص MaxMind','Apply'=>'طبِّق','Please note: without a free MaxMind key, your geolocation calls will be limited and your site performance may be impacted.'=>'يرجى ملاحظة: بدون مفتاح MaxMind مجاني، ستكون طلبات تحديد الموقع الجغرافي محدودة وقد يتأثر أداء موقعك.','Learn how to generate a free license key'=>'تعرف على كيفية إنشاء مفتاح ترخيص مجاني','Set on %s'=>'تم التعيين في %s','Country availability'=>'التوفر حسب الدولة','All countries except'=>'جميع الدول باستثناء','Configure per country availability for this payment gateway'=>'تكوين التوفر لكل دولة لبوابة الدفع هذه','Save changes'=>'حفظ التغييرات','Settings saved.'=>'تم حفظ الإعدادات.','Error saving settings.'=>'خطأ في حفظ الإعدادات.','We noticed that you\'re using WooCommerce Gateways Country Limiter plugin which is now integrated into WPML Multilingual & Multicurrency for WooCommerce. Please remove it!'=>'لاحظنا أنك تستخدم إضافة WooCommerce Gateways Country Limiter المدمجة الآن في WPML Multilingual & Multicurrency for WooCommerce. يرجى إزالتها!','To translate custom text for payment methods, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة النصوص المخصصة لطرق الدفع، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','To translate permalinks for product taxonomies, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'لترجمة الروابط الدائمة لتصنيفات المنتجات، انتقل إلى %1$sWPML Multilingual & Multicurrency for WooCommerce ← عناوين URL للمتجر%2$s.','To translate product permalinks, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'لترجمة الروابط الدائمة للمنتجات، انتقل إلى %1$sWPML Multilingual & Multicurrency for WooCommerce ← عناوين URL للمتجر%2$s.','How to translate permalinks for product taxonomies'=>'كيفية ترجمة الروابط الدائمة لتصنيفات المنتجات','How to translate product permalinks'=>'كيفية ترجمة الروابط الدائمة للمنتجات','Translate WooCommerce products'=>'ترجمة منتجات WooCommerce','Translate shipping classes'=>'ترجمة فئات الشحن','Configure multicurrency for multilingual sites'=>'تكوين العملات المتعددة للمواقع متعددة اللغات','Translate endpoints'=>'ترجمة نقاط النهاية','How to translate this?'=>'كيف تترجم هذا؟','WPML Multilingual & Multicurrency for WooCommerce will use cookies to understand the basket info when using languages in domains and to transfer data between the domains.'=>'سيستخدم WPML Multilingual & Multicurrency for WooCommerce ملفات تعريف الارتباط (cookies) لفهم معلومات السلة عند استخدام اللغات في النطاقات ولنقل البيانات بين النطاقات.','WPML Multilingual & Multicurrency for WooCommerce will also use cookies to identify the language and currency of each customer’s order as well as the currency of the reports created by WooCommerce. WPML Multilingual & Multicurrency for WooCommerce extends these reports by adding the currency’s information.'=>'سيستخدم WPML Multilingual & Multicurrency for WooCommerce أيضًا ملفات تعريف الارتباط لتحديد لغة وعملة طلب كل عميل بالإضافة إلى عملة التقارير التي ينشئها WooCommerce. يقوم WPML Multilingual & Multicurrency for WooCommerce بتوسيع هذه التقارير عن طريق إضافة معلومات العملة.','Invalid currency parameter: "%s"'=>'معلمة عملة غير صالحة: ”%s“','Invalid language parameter: "%s"'=>'معلمة لغة غير صالحة: ”%s“','Product not found: %d'=>'المنتج غير موجود: %d','Term not found: %d'=>'المصطلح غير موجود: %d','Using "translation_of" requires providing a "lang" parameter too'=>'استخدام ”translation_of“ يتطلب توفير معلمة ”lang“ أيضًا','Multilingual'=>'متعدد اللغات','Multicurrency'=>'العملات المتعددة','To run your store in multiple languages, you need to use the %1$sWPML plugin%2$s.'=>'لتشغيل متجرك بلغات متعددة، تحتاج إلى استخدام %1$sإضافة WPML%2$s.','If you have it already, install and activate it. Otherwise, %1$sbuy WPML%2$s.'=>'إذا كانت لديك بالفعل، فقم بتثبيتها وتفعيلها. خلاف ذلك، %1$sاشترِ WPML%2$s.','You will need either the Multilingual CMS or Multilingual Agency package to use WPML with WooCommerce.'=>'ستحتاج إما إلى حزمة Multilingual CMS أو Multilingual Agency لاستخدام WPML مع WooCommerce.','You can still use the %1$smulticurrency features%2$s without buying anything.'=>'لا يزال بإمكانك استخدام %1$sميزات العملات المتعددة%2$s دون شراء أي شيء.','%s translation'=>'ترجمة %s','Translating %1$s? Use the %2$s table for easier translation.'=>'هل تترجم %1$s؟ استخدم جدول %2$s لترجمة أسهل.','To translate product details, including their taxonomy, use this dashboard. If you need to translate taxonomy independently or adjust store and currency settings, visit: %1$sWPML Multilingual & Multicurrency for WooCommerce documentation%2$s.'=>'لترجمة تفاصيل المنتج، بما في ذلك تصنيفاتها، استخدم لوحة التحكم هذه. إذا كنت بحاجة إلى ترجمة التصنيفات بشكل مستقل أو ضبط إعدادات المتجر والعملة، فقم بزيارة: %1$sوثائق WPML Multilingual & Multicurrency for WooCommerce%2$s.','To translate this content, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة هذا المحتوى، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','To see how to translate this text, save your changes here first.'=>'لمعرفة كيفية ترجمة هذا النص، احفظ تغييراتك هنا أولاً.','Header alignment for translations'=>'محاذاة الرأس للترجمات','Automatically align email headers based on%slanguage direction (right-to-left or left-to-right).'=>'محاذاة رؤوس رسائل البريد الإلكتروني تلقائيًا بناءً على%sاتجاه اللغة (من اليمين إلى اليسار أو من اليسار إلى اليمين).','Off – use the "Header alignment" setting above'=>'إيقاف – استخدم إعداد ”محاذاة الرأس“ أعلاه','On – align automatically'=>'تشغيل – المحاذاة تلقائيًا','Introduction'=>'مقدمة','Store Pages'=>'صفحات المتجر','Global Attributes'=>'السمات العامة','Multiple Currencies'=>'عملات متعددة','Tour Data'=>'بيانات الجولة','Title'=>'العنوان','Content'=>'المحتوى','To translate the Method Title, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة عنوان الطريقة، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','To translate Labels, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة التسميات، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','To translate custom product fields, save your changes here first, then go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة حقول المنتج المخصصة، احفظ تغييراتك هنا أولاً، ثم انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','Calculate costs in other currencies automatically'=>'حساب التكاليف بالعملات الأخرى تلقائيًا','Set costs in other currencies manually'=>'تعيين التكاليف بالعملات الأخرى يدويًا','Bookings'=>'الحجوزات','Resources Label'=>'تسمية الموارد','Resources'=>'الموارد','Person Types'=>'أنواع الأشخاص','Person Type Name'=>'اسم نوع الشخص','Description'=>'الوصف','Resources label'=>'تسمية الموارد','To translate Resources, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'لترجمة الموارد، انتقل إلى %1$sلوحة إدارة الترجمة%2$s وأرسل المنتج المرتبط للترجمة.','To translate Person Types, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'لترجمة أنواع الأشخاص، انتقل إلى %1$sلوحة إدارة الترجمة%2$s وأرسل المنتج المرتبط للترجمة.','Booking currency'=>'عملة الحجز','Composite Products ( Components )'=>'المنتجات المركبة (المكونات)','Name'=>'الاسم','Composite Products ( Scenarios )'=>'المنتجات المركبة (السيناريوهات)','To translate global add-ons, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة الإضافات العامة، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','Product Add-ons Group "%s"'=>'مجموعة إضافات المنتج ”%s“','Placeholder'=>'نص نائِب','Options'=>'خيارات','Label'=>'تسمية','To translate per-product add-ons, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'لترجمة إضافات كل منتج، انتقل إلى %1$sلوحة إدارة الترجمة%2$s وأرسل المنتج المرتبط للترجمة.','Multi-currency settings'=>'إعدادات العملات المتعددة','Calculate prices in other currencies automatically'=>'حساب الأسعار بالعملات الأخرى تلقائيًا','Set prices in other currencies manually'=>'تعيين الأسعار بالعملات الأخرى يدويًا','Here you can set different prices for the %s in multiple currencies:'=>'هنا يمكنك تعيين أسعار مختلفة لـ %s بعملات متعددة:','Product Bundles'=>'حزم المنتجات','You can translate text for subscription products from the %1$sTranslation Dashboard%2$s.'=>'يمكنك ترجمة نص منتجات الاشتراك من %1$sلوحة إدارة الترجمة%2$s.','Subscription Price'=>'سعر الاشتراك','Sign-up Fee'=>'رسوم التسجيل','Product tabs'=>'تبويبات المنتج','Heading'=>'العنوان','To translate custom per-product tabs, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'لترجمة تبويبات كل منتج المخصصة، انتقل إلى %1$sلوحة إدارة الترجمة%2$s وأرسل المنتج المرتبط للترجمة.','Custom Tabs'=>'تبويبات مخصصة','Tab Title'=>'عنوان التبويب','Quick Edit isn\'t available for product translations:'=>'التحرير السريع غير متاح لترجمات المنتجات:','- To edit this product\'s translation, use the %1$sTranslation Dashboard%2$s.'=>'- لتعديل ترجمة هذا المنتج، استخدم %1$sلوحة إدارة الترجمة%2$s.','- To edit the original product, switch back to the default language.'=>'- لتعديل المنتج الأصلي، عد إلى اللغة الافتراضية.','Multilingual Settings'=>'إعدادات متعدد اللغات','Multicurrency Settings'=>'إعدادات العملات المتعددة','It’s recommended that you translate products from the %1$sTranslation Dashboard%2$s.'=>'نوصي بترجمة المنتجات من %1$sلوحة إدارة الترجمة%2$s.','WCML'=>'WCML','Shows a list of the products that existed in the cart before the cart is reset on the front end after switching the language or the currency. It will be hidden when there are no products to show.'=>'يعرض قائمة بالمنتجات التي كانت موجودة في سلة المشتريات قبل إعادة تعيين السلة في الواجهة الأمامية بعد تبديل اللغة أو العملة. سيتم إخفاؤه عندما لا تكون هناك منتجات لعرضها.','Products before cart reset'=>'المنتجات قبل إعادة تعيين السلة','Switching language?'=>'تبديل اللغة؟','You\'ve switched the language and there are items in the cart. If you keep the %s language, the cart will be emptied and you will have to add the items again to the cart.'=>'لقد قمت بتبديل اللغة وهناك عناصر في سلة المشتريات. إذا احتفظت باللغة %s، فسيتم إفراغ السلة وسيتعين عليك إضافة العناصر مرة أخرى إليها.','Keep %s'=>'الاحتفاظ بـ %s','Switch back to %s'=>'العودة إلى %s','Reset cart option warning 1Because of some elements in your site configuration, when the users switch the currency or the language on the front end, the cart content might not be synchronized correctly.'=>'بسبب بعض العناصر في تكوين موقعك، عندما يقوم المستخدمون بتبديل العملة أو اللغة في الواجهة الأمامية، قد لا تتم مزامنة محتوى سلة المشتريات بشكل صحيح.','Reset cart option warning 2It is recommended that you %s with the option to reset the cart in a situation like this.'=>'نوصي بأن تقوم بـ %s مع خيار إعادة تعيين سلة المشتريات في مثل هذه الحالة.','configure WPML Multilingual & Multicurrency for WooCommerce'=>'تكوين WPML Multilingual & Multicurrency for WooCommerce','More details'=>'مزيد من التفاصيل','Switching currency?'=>'تبديل العملة؟','Your cart is not empty! After you switched the currency, all items from the cart will be removed and you have to add them again.'=>'سلة المشتريات ليست فارغة! بعد تبديل العملة، ستتم إزالة جميع العناصر من السلة وسيتعين عليك إضافتها مرة أخرى.','Keep using %s'=>'الاستمرار في استخدام %s','Proceed'=>'متابعة','Show reviews in all languages  (%s)'=>'إظهار التقييمات بجميع اللغات (%s)','Show only reviews in %1$s (%2$s)'=>'إظهار التقييمات بـ %1$s فقط (%2$s)','translated'=>'مترجم','Show original'=>'إظهار الأصل','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML</a> versions prior %2$s.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال. إنه غير متوافق مع إصدارات <a href="%1$s">WPML</a> الأقدم من %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. Please finish the installation of WPML first.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال. يرجى إنهاء تثبيت WPML أولاً.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">Woocommerce</a> versions prior %2$s.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال. إنه غير متوافق مع إصدارات <a href="%1$s">WooCommerce</a> الأقدم من %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML String Translation</a> versions prior %2$s.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال. إنه غير متوافق مع إصدارات <a href="%1$s">WPML String Translation</a> الأقدم من %2$s.','WPML support'=>'دعم WPML','Default taxonomies must be translatable: 1/6Some taxonomies in your site are forced to be untranslatable. This is causing a problem when you\'re trying to run a multilingual WooCommerce site.'=>'بعض التصنيفات في موقعك مجبرة على أن تكون غير قابلة للترجمة. يتسبب هذا في مشكلة عندما تحاول تشغيل موقع WooCommerce متعدد اللغات.','Default taxonomies must be translatable: 2/6A plugin or the theme are probably doing this.'=>'من المحتمل أن تكون إضافة أو القالب هما من يقومان بذلك.','Default taxonomies must be translatable: 3/6What you can do:'=>'ما يمكنك فعله:','Default taxonomies must be translatable: 4/61. Temporarily disable plugins and see if this message disappears.'=>'1. قم بتعطيل الإضافات مؤقتًا ومعرفة ما إذا كانت هذه الرسالة ستختفي.','Default taxonomies must be translatable: 5/62. Temporarily switch the theme and see if this message disappears.'=>'2. قم بتبديل القالب مؤقتًا ومعرفة ما إذا كانت هذه الرسالة ستختفي.','Default taxonomies must be translatable: 6/6It\'s best to contact %s, tell that you\'re getting this message and offer to send a Duplicator copy of the site. We will work with the theme/plugin author and fix the problem for good. In the meanwhile, we\'ll give you a temporary solution, so you\'re not stuck.'=>'من الأفضل الاتصال بـ %s، وإخبارهم بأنك تتلقى هذه الرسالة وعرض إرسال نسخة Duplicator من الموقع. سنعمل مع مؤلف القالب/الإضافة ونصلح المشكلة نهائيًا. في غضون ذلك، سنقدم لك حلاً مؤقتًا حتى لا تتوقف.','and'=>'و','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It requires %s in order to work.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال. يتطلب %s لكي يعمل.','Please %1$sactivate %2$s%3$s.'=>'يرجى %1$sتفعيل %2$s%3$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective.'=>'تم تمكين WPML Multilingual & Multicurrency for WooCommerce ولكنه غير فعال.','Because this site uses the default permalink structure, you cannot use slug translation for product permalinks.'=>'نظرًا لأن هذا الموقع يستخدم بنية الروابط الدائمة الافتراضية، لا يمكنك استخدام ترجمة الاسم اللطيف لروابط المنتجات الدائمة.','Please choose a different permalink structure or disable slug translation.'=>'يرجى اختيار بنية روابط دائمة مختلفة أو تعطيل ترجمة الاسم اللطيف.','Permalink settings'=>'إعدادات الروابط الدائمة','Configure products slug translation'=>'تكوين ترجمة الاسم اللطيف للمنتجات','wpml-config.xml file missing from WPML Multilingual & Multicurrency for WooCommerce folder.'=>'ملف wpml-config.xml مفقود من مجلد WPML Multilingual & Multicurrency for WooCommerce.','Custom field %s configuration from wpml-config.xml file was altered!'=>'تم تغيير تكوين الحقل المخصص %s من ملف wpml-config.xml!','Custom type %s configuration from wpml-config.xml file was altered!'=>'تم تغيير تكوين النوع المخصص %s من ملف wpml-config.xml!','Custom taxonomy %s configuration from wpml-config.xml file was altered!'=>'تم تغيير تكوين التصنيف المخصص %s من ملف wpml-config.xml!','We detected a problem in your WPML configuration: the %1$sproduct_type%2$s taxonomy is set as translatable and this would cause problems with translated products. You can fix this in the %3$sMultilingual Content Setup page%4$s.'=>'اكتشفنا مشكلة في تكوين WPML الخاص بك: تم تعيين التصنيف %1$sproduct_type%2$s كقابل للترجمة وهذا من شأنه أن يسبب مشاكل مع المنتجات المترجمة. يمكنك إصلاح ذلك في %3$sصفحة إعداد المحتوى متعدد اللغات%4$s.','We detected that the %1$sproduct_type%2$s field was set incorrectly for some product translations. This happened because the product_type taxonomy was translated. You can fix this in the WPML Multilingual & Multicurrency for WooCommerce %3$stroubleshooting page%4$s.'=>'اكتشفنا أنه تم تعيين الحقل %1$sproduct_type%2$s بشكل غير صحيح لبعض ترجمات المنتجات. حدث هذا بسبب ترجمة التصنيف product_type. يمكنك إصلاح ذلك في %3$sصفحة استكشاف الأخطاء وإصلاحها%4$s لـ WPML Multilingual & Multicurrency for WooCommerce.','Downloading translations... Please don\'t close this page.'=>'جاري تنزيل الترجمات... يرجى عدم إغلاق هذه الصفحة.','Order language:'=>'لغة الطلب:','All the products will be removed from the current order in order to change the language'=>'ستتم إزالة جميع المنتجات من الطلب الحالي لتغيير اللغة','Quick edit "%s" inline'=>'تحرير سريع لـ ”%s“ مضمن','Quick Edit'=>'تحرير سريع','Your settings have been saved.'=>'تم حفظ إعداداتك.','You do not have permission to perform this action.'=>'ليس لديك إذن للقيام بهذا الإجراء.','Choose a file'=>'اختر ملفًا','At least one of these fields is required: title, content or excerpt'=>'مطلوب واحد على الأقل من هذه الحقول: العنوان أو المحتوى أو المقتطف','This translation job will no longer be assigned to you. Other translators will be able take it and continue the translation.'=>'لن يتم تعيين وظيفة الترجمة هذه لك بعد الآن. سيتمكن المترجمون الآخرون من استلامها ومتابعة الترجمة.','This field is locked for editing because WPML will copy its value from the original language.'=>'هذا الحقل مقفل للتحرير لأن WPML سيقوم بنسخ قيمته من اللغة الأصلية.','This is a translation of %1$s. Some of the fields are not editable. It\'s recommended that you translate products from the %2$sTranslation Dashboard%3$s.'=>'هذه ترجمة لـ %1$s. بعض الحقول غير قابلة للتحرير. نوصي بترجمة المنتجات من %2$sلوحة إدارة الترجمة%3$s.','Cart'=>'سلة المشتريات','Checkout'=>'إتمام الطلب','Checkout &rarr; Pay'=>'إتمام الطلب ← دفع','Order Received'=>'تم استلام الطلب','My Account'=>'حسابي','Change Password'=>'تغيير كلمة المرور','Edit My Address'=>'تعديل عنواني','Logout'=>'تسجيل الخروج','Lost Password'=>'فقدت كلمة المرور','View Order'=>'عرض الطلب','Shop'=>'المتجر','To quickly translate this and other WooCommerce store pages, please run the %1$ssetup wizard%2$s.'=>'لترجمة هذه الصفحات وصفحات متجر WooCommerce الأخرى بسرعة، يرجى تشغيل %1$sمعالج الإعداد%2$s.','To translate %1$s please use the %2$s translation%3$s page, inside the %4$sWPML Multilingual & Multicurrency for WooCommerce admin%5$s.'=>'لترجمة %1$s يرجى استخدام صفحة ترجمة %2$s%3$s، داخل %4$sمسؤول WPML Multilingual & Multicurrency for WooCommerce%5$s.','%d products left'=>'تبقى %d منتجات','Synchronization complete!'=>'اكتملت المزامنة!','Invalid taxonomy %s'=>'تصنيف غير صالح %s','Some translated %1$s have different %2$s assignments.'=>'بعض %1$s المترجمة لها تعيينات %2$s مختلفة.','Update %1$s for all translated %2$s'=>'تحديث %1$s لجميع %2$s المترجمة','All %1$s have the same %2$s assignments.'=>'جميع %1$s لها نفس تعيينات %2$s.','Successfully updated %1$s for all translated %2$s.'=>'تم تحديث %1$s بنجاح لجميع %2$s المترجمة.','Product Base'=>'قاعدة المنتج','Product Tag Base'=>'قاعدة وسم المنتج','Product Category Base'=>'قاعدة تصنيف المنتج','Product Attribute Base'=>'قاعدة سمة المنتج','Attribute Slug'=>'الاسم اللطيف للسمة','Endpoint: %s'=>'نقطة النهاية: %s','You are using the same value as for the regular category base. This is known to create conflicts resulting in urls not working properly.'=>'أنت تستخدم نفس القيمة المستخدمة لقاعدة التصنيف العادية. من المعروف أن هذا يؤدي إلى تعارضات تؤدي إلى عدم عمل عناوين URL بشكل صحيح.','To translate attributes, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'لترجمة السمات، انتقل إلى %1$sلوحة إدارة الترجمة%2$s وأرسل المنتج المرتبط للترجمة.','The default currency was changed. In order to show accurate prices in all currencies, you need to update the exchange rates under the %1$sMulti-currency%2$s configuration.'=>'تم تغيير العملة الافتراضية. من أجل إظهار أسعار دقيقة بجميع العملات، تحتاج إلى تحديث أسعار الصرف ضمن تكوين %1$sالعملات المتعددة%2$s.','Show all currencies'=>'إظهار كافة العملات','Order currency:'=>'عملة الطلب:','All the products will be removed from the current order in order to change the currency'=>'ستتم إزالة جميع المنتجات من الطلب الحالي لتغيير العملة','Currencies order updated'=>'تم تحديث ترتيب العملات','Uploads'=>'الوسائط المرفوعة','Currency switcher'=>'مبدل العملة','Customize the currency switcher'=>'تخصيص مبدل العملة','You haven\'t added any secondary currencies.'=>'لم تقم بإضافة أي عملات ثانوية.','Use custom settings for translations download files'=>'استخدام إعدادات مخصصة لملفات تنزيل الترجمات','Use the same files for translations'=>'استخدام نفس الملفات للترجمات','Add separate download files for translations when you translate this product'=>'إضافة ملفات تنزيل منفصلة للترجمات عند ترجمة هذا المنتج','You have untranslated terms!'=>'لديك مصطلحات غير مترجمة!','Store URLs'=>'عناوين URL للمتجر','Status'=>'الحالة','Troubleshooting'=>'استكشاف الأخطاء وإصلاحها','Translate Products'=>'ترجمة المنتجات','Go to WPML &rarr; Translation Dashboard to translate Products'=>'انتقل إلى WPML ← لوحة إدارة الترجمة لترجمة المنتجات','Translate Taxonomy'=>'ترجمة التصنيف','Go to WPML &rarr; Taxonomy Translation to translate Taxonomy terms manually'=>'انتقل إلى WPML ← ترجمة التصنيفات لترجمة مصطلحات التصنيف يدويًا','Prefer to translate manually?'=>'هل تفضل الترجمة يدويًا؟','To manually translate products, go to %1$sProducts%2$s and click on the "plus" icon.'=>'لترجمة المنتجات يدويًا، انتقل إلى %1$sالمنتجات%2$s وانقر على أيقونة ”زائد“.','To manually translate product categories, tags and attributes, go to %1$sWPML &rarr; Taxonomy Translation%2$s.'=>'لترجمة تصنيفات ووسوم وسمات المنتجات يدويًا، انتقل إلى %1$sWPML ← ترجمة التصنيفات%2$s.','Translation'=>'الترجمة','Translate the WooCommerce slugs (Shop, Product base, etc.) at WPML → Translations → Store URLs.'=>'ترجم الأسماء اللطيفة لـ WooCommerce (المتجر، قاعدة المنتج، إلخ) في WPML ← الترجمات ← عناوين URL للمتجر.','Open Store URLs ›'=>'فتح عناوين URL للمتجر ›','Go to WPML → Translations → Dashboard to translate Products.'=>'انتقل إلى WPML ← الترجمات ← لوحة التحكم لترجمة المنتجات.','Translate Products ›'=>'ترجمة المنتجات ›','Translate product taxonomies'=>'ترجمة تصنيفات المنتجات','Go to WPML → Translations → Taxonomy to translate product categories, tags and attributes.'=>'انتقل إلى WPML ← الترجمات ← التصنيف لترجمة تصنيفات ووسوم وسمات المنتجات.','Translate Taxonomies ›'=>'ترجمة التصنيفات ›','Products, media, downloads, reviews, cart and the variation translation sync — all in WPML → Settings → WCML.'=>'المنتجات، والوسائط، والتنزيلات، والتقييمات، وسلة المشتريات، ومزامنة ترجمة التنويعات — كل ذلك في WPML ← إعدادات ← WCML.','Open WCML Settings ›'=>'فتح إعدادات WCML ›','Configure currencies, exchange rates and currency switchers at WPML → Settings → Multicurrency.'=>'قم بتكوين العملات وأسعار الصرف ومبدلات العملات في WPML ← إعدادات ← العملات المتعددة.','Open Multicurrency ›'=>'فتح العملات المتعددة ›','Support'=>'الدعم','WCML status'=>'حالة WCML','Diagnostic checks for store pages, products, taxonomies, multicurrency and plugins.'=>'فحوصات تشخيصية لصفحات المتجر والمنتجات والتصنيفات والعملات المتعددة والإضافات.','Open WCML status ›'=>'فتح حالة WCML ›','Fix WCML translations'=>'إصلاح ترجمات WCML','Safe bulk tools to sync product variations, galleries and stock; register missing reviews; create missing attribute translations.'=>'أدوات جماعية آمنة لمزامنة تنويعات المنتجات والمعارض والمخزون؛ وتسجيل التقييمات المفقودة؛ وإنشاء ترجمات السمات المفقودة.','Open Fix WCML translations ›'=>'فتح إصلاح ترجمات WCML ›','WCML configuration log'=>'سجل تكوين WCML','Read-only snapshot of the WCML configuration. Copy when WPML Support asks.'=>'لقطة للقراءة فقط لتكوين WCML. انسخها عندما يطلب دعم WPML ذلك.','Open WCML configuration log ›'=>'فتح سجل تكوين WCML ›','WCML translation maintenance'=>'صيانة ترجمة WCML','Advanced repair tools — only run when WPML Support asks you to.'=>'أدوات إصلاح متقدمة — لا تقم بتشغيلها إلا عندما يطلب منك دعم WPML ذلك.','Open WCML translation maintenance ›'=>'فتح صيانة ترجمة WCML ›','WPML is installed on this site, so WCML\'s controls have moved into WPML. Pick the area you need.'=>'تم تثبيت WPML على هذا الموقع، لذا انتقلت عناصر تحكم WCML إلى WPML. اختر المنطقة التي تحتاجها.','Translatable?'=>'قابلة للترجمة؟','Enable this if you want to translate attribute values with WPML Multilingual & Multicurrency for WooCommerce'=>'قم بتمكين هذا إذا كنت تريد ترجمة قيم السمات باستخدام WPML Multilingual & Multicurrency for WooCommerce','Existing translations and variations associated will be deleted.'=>'سيتم حذف الترجمات والتنويعات المرتبطة الموجودة.','Products removed after switching to %s:'=>'المنتجات التي تمت إزالتها بعد التبديل إلى %s:','Clear list'=>'مسح القائمة','Products Synchronization'=>'مزامنة المنتجات','Configure specific product properties that should be synced to translations.'=>'تكوين خصائص منتج معينة يجب مزامنتها مع الترجمات.','Sync publishing date for translated products.'=>'مزامنة تاريخ النشر للمنتجات المترجمة.','Sync products and product taxonomies order.'=>'مزامنة ترتيب المنتجات وتصنيفات المنتجات.','Products Media Synchronization'=>'مزامنة وسائط المنتجات','Configure thumbnail and gallery synchronization to translations.'=>'تكوين مزامنة الصورة المصغرة والمعرض للترجمات.','Display original images on the translated product front page if images not specified'=>'عرض الصور الأصلية في صفحة المنتج المترجمة إذا لم يتم تحديد صور','Products Download Files'=>'ملفات تنزيل المنتجات','If you are using downloadable products, you can choose to have their paths
                                            synchronized, or seperate for each language.'=>'إذا كنت تستخدم منتجات قابلة للتنزيل، يمكنك اختيار مزامنة مساراتها 
 أو جعلها منفصلة لكل لغة.','Add separate download files for translations when translating products'=>'إضافة ملفات تنزيل منفصلة للترجمات عند ترجمة المنتجات','Product reviews'=>'تقييمات المنتج','Define how to display product reviews on the product page by default. The customer will be still able to filter reviews by language.'=>'حدد كيفية عرض تقييمات المنتج في صفحة المنتج افتراضيًا. سيظل العميل قادرًا على تصفية التقييمات حسب اللغة.','By default, show reviews in all languages'=>'بشكل افتراضي، إظهار التقييمات بجميع اللغات','You can choose to clear the cart contents when you change language or currency in case you have problems in cart or checkout page'=>'يمكنك اختيار مسح محتويات سلة المشتريات عند تغيير اللغة أو العملة في حال واجهت مشكلات في صفحة السلة أو إتمام الطلب','Switching languages when there are items in the cart'=>'تبديل اللغات عند وجود عناصر في سلة المشتريات','Synchronize cart content when switching languages'=>'مزامنة محتوى سلة المشتريات عند تبديل اللغات','Prompt for a confirmation and reset the cart'=>'طلب تأكيد وإعادة تعيين سلة المشتريات','Switching currencies when there are items in the cart'=>'تبديل العملات عند وجود عناصر في سلة المشتريات','Synchronize cart content when switching currencies'=>'مزامنة محتوى سلة المشتريات عند تبديل العملات','This feature was disabled. Please enable %1$sWPML cookies%2$s to continue.'=>'تم تعطيل هذه الميزة. يرجى تمكين %1$sملفات تعريف ارتباط WPML%2$s للمتابعة.','Not sure which option to choose? Read about %1$spotential issues when switching languages and currencies while the cart has items%2$s.'=>'لست متأكدًا من الخيار الذي يجب اختياره؟ اقرأ عن %1$sالمشكلات المحتملة عند تبديل اللغات والعملات بينما تحتوي سلة المشتريات على عناصر%2$s.','Product Translation Interface'=>'واجهة ترجمة المنتج','The recommended way is using the WPML Translation Editor. It is streamlined for making the translation process much easier while also providing a much better integration with various WooCommerce extensions.'=>'الطريقة الموصى بها هي استخدام محرر ترجمة WPML. فهو مصمم لجعل عملية الترجمة أسهل بكثير مع توفير تكامل أفضل مع ملحقات WooCommerce المتنوعة.','WPML Translation Editor'=>'محرر ترجمة WPML','Native WooCommerce product editing screen'=>'شاشة تحرير منتج WooCommerce الأصلية','If you are using a page builder to design WooCommerce products, you should only use WPML\'s Translation Editor.'=>'إذا كنت تستخدم أداة بناء صفحات لتصميم منتجات WooCommerce، فيجب عليك استخدام محرر ترجمة WPML فقط.','OK (translate with the WordPress editor)'=>'موافق (الترجمة باستخدام محرر WordPress)','Cancel (stay with the Translation Editor)'=>'إلغاء (البقاء مع محرر الترجمة)','Set different slugs in different languages for %s on WPML Multilingual & Multicurrency for WooCommerce URLs translations page'=>'تعيين أسماء لطيفة مختلفة بلغات مختلفة لـ %s في صفحة ترجمة عناوين URL لـ WPML Multilingual & Multicurrency for WooCommerce','To translate the attribute slug, please set the option "Enable archives?" for the attribute %s in WooCommerce'=>'لترجمة الاسم اللطيف للسمة، يرجى تعيين خيار ”تمكين الأرشيفات؟“ للسمة %s في WooCommerce','Synchronize attributes and update product variations'=>'مزامنة السمات وتحديث تنويعات المنتج','This will automatically generate variations for translated products corresponding to recently translated attributes.'=>'سيؤدي هذا تلقائيًا إلى إنشاء تنويعات للمنتجات المترجمة المقابلة للسمات المترجمة مؤخرًا.','Currently, there are %s variations that need to be created.'=>'حاليًا، هناك %s تنويعًا يجب إنشاؤها.','Synchronize %s assignment in content'=>'مزامنة تعيين %s في المحتوى','This action lets you automatically apply the %s taxonomy to your content in different languages. It will scan the original content and apply the same taxonomy to translated content.'=>'يتيح لك هذا الإجراء تطبيق تصنيف %s تلقائيًا على محتواك بلغات مختلفة. سيقوم بفحص المحتوى الأصلي وتطبيق التصنيف نفسه على المحتوى المترجم.','Please make a backup of your database before using these tools'=>'يرجى عمل نسخة احتياطية لقاعدة بياناتك قبل استخدام هذه الأدوات','There are <strong>%s product(s)</strong> in total.'=>'يوجد <strong>%s منتجًا</strong> في الإجمالي.','There are <strong>%s product(s)</strong> with variations.'=>'يوجد <strong>%s منتجًا</strong> بتنويعات.','There are <strong>%s variation(s)</strong> in total.'=>'يوجد <strong>%s تنويعًا</strong> في الإجمالي.','Synchronize data into translations'=>'مزامنة البيانات في الترجمات','Synchronize product variations'=>'مزامنة تنويعات المنتج','Synchronize products image galleries'=>'مزامنة معارض صور المنتجات','Synchronize metadata for product categories (display type, thumbnail)'=>'مزامنة البيانات الوصفية لفئات المنتجات (نوع العرض، الصورة المصغرة)','Synchronize stock for products and product variations'=>'مزامنة المخزون للمنتجات وتنويعات المنتجات','Fix multilingual information'=>'إصلاح المعلومات متعددة اللغات','Fix incorrect or missing translation links for product variations'=>'إصلاح روابط الترجمة غير الصحيحة أو المفقودة لتنويعات المنتج','Fix product taxonomies'=>'إصلاح تصنيفات المنتج','Set product types as not translatable and delete unwanted translations'=>'تعيين أنواع المنتجات كغير قابلة للترجمة وحذف الترجمات غير المرغوب فيها','Create missing translations for product attributes:'=>'إنشاء الترجمات المفقودة لسمات المنتج:','To translate product taxonomies, go to the %1$sTaxonomy Translation%2$s page.'=>'لترجمة تصنيفات المنتج، انتقل إلى صفحة %1$sترجمة التصنيفات%2$s.','none'=>'لا يوجد','Fix missing product reviews'=>'إصلاح تقييمات المنتج المفقودة','Allow to translate missing product reviews'=>'السماح بترجمة تقييمات المنتج المفقودة','To translate product reviews, go to the %1$sTranslation Dashboard%2$s.'=>'لترجمة تقييمات المنتج، انتقل إلى %1$sلوحة إدارة الترجمة%2$s.','Cleanup tools'=>'أدوات التنظيف','Remove unused custom fields from product and variation translations'=>'إزالة الحقول المخصصة غير المستخدمة من ترجمات المنتجات والتنويعات','Run the selected tools'=>'تشغيل الأدوات المختارة','Processing'=>'جارٍ المعالجة','WPML Multilingual & Multicurrency for WooCommerce settings'=>'إعدادات WPML Multilingual & Multicurrency for WooCommerce','%s items processed'=>'تمت معالجة %s عنصرًا','Processing...'=>'جارٍ المعالجة...','Completed'=>'مكتمل','Something went wrong, please reload the page and try again'=>'حدث خطأ ما، يرجى إعادة تحميل الصفحة والمحاولة مرة أخرى','Clear all colors'=>'مسح كافة الألوان','Gray'=>'رمادي','White'=>'أبيض','Blue'=>'أزرق','Border'=>'الحدود','Current currency font color'=>'لون خط العملة الحالية','Other currency font color'=>'لون خط العملات الأخرى','Current currency background color'=>'لون خلفية العملة الحالية','Other currency background color'=>'لون خلفية العملات الأخرى','Currency switcher style'=>'نمط مبدل العملة','Core'=>'الأساسي','Custom'=>'مخصص','Allowed HTML tags: <img> <span> <u> <strong> <em>'=>'علامات HTML المسموح بها: <img> <span> <u> <strong> <em>','Template for currency switcher'=>'قالب مبدل العملة','Available parameters'=>'المعلمات المتاحة','Default: %name% (%1$symbol%) - %2$code%'=>'افتراضي: %name% (%1$symbol%) - %2$code%','Hide more'=>'إخفاء المزيد','You can customize the currency switcher template using these parameters:'=>'يمكنك تخصيص قالب مبدل العملة باستخدام هذه المعلمات:','%1$s: Full name of the currency (e.g., “Euro”).'=>'%1$s: الاسم الكامل للعملة (مثل ”Euro“).','%1$s: Standard symbol representing the currency (e.g., “$” or “€”).'=>'%1$s: الرمز القياسي الذي يمثل العملة (مثل ”$“ أو ”€“).','%1$s: Standard code representing the currency (e.g., USD for United States Dollar).'=>'%1$s: الرمز القياسي الذي يمثل العملة (مثل USD للدولار الأمريكي).','Additionally, you can use HTML tags %1$s(img, span, em, strong, u)%2$s to customize the output when the switcher style is set to %1$sList of currencies%2$s, %3$sin line with official HTML standards for the select tag%4$s.'=>'بالإضافة إلى ذلك، يمكنك استخدام علامات HTML %1$s(img, span, em, strong, u)%2$s لتخصيص المخرجات عندما يتم ضبط نمط المبدل على %1$sقائمة العملات%2$s، %3$sبما يتماشى مع معايير HTML الرسمية لعلامة select%4$s.','Currency switcher colors'=>'ألوان مبدل العملة','Color theme'=>'سمة اللون','Normal'=>'عادي','Hover'=>'تمرير الماوس','Select a preset'=>'اختر إعدادًا مسبقًا','Widget area'=>'منطقة ودجت','Widget title'=>'عنوان الودجت','-- Choose a widget area --'=>'-- اختر منطقة ودجت --','Preview'=>'معاينة','Regular Price'=>'السعر الافتراضي','Sale Price'=>'سعر التخفيض','Multi-currency is enabled, but no secondary currencies have been set. %1$sAdd secondary currency%2$s.'=>'تعدد العملات مُمكّن، ولكن لم يتم تعيين أي عملات ثانوية. %1$sأضف عملة ثانوية%2$s.','Click to see the prices in the other currencies as they are currently shown on the front end.'=>'انقر لرؤية الأسعار بالعملات الأخرى كما تظهر حاليًا في الواجهة الأمامية.','Show'=>'عرض','Hide'=>'إخفاء','Enter prices in other currencies'=>'أدخل الأسعار بالعملات الأخرى','Hide prices in other currencies'=>'إخفاء الأسعار بالعملات الأخرى','Determined automatically based on exchange rate'=>'يتم تحديده تلقائيًا بناءً على سعر الصرف','Schedule'=>'جدولة','Same as default currency'=>'نفس العملة الافتراضية','Set dates'=>'تعيين التواريخ','Collapse'=>'طي','From&hellip;'=>'من&hellip;','To&hellip;'=>'إلى&hellip;','Please enter in a value less than the regular price'=>'يرجى إدخال قيمة أقل من السعر الافتراضي','never'=>'أبدًا','Automatic Exchange Rates'=>'أسعار الصرف التلقائية','Enable automatic exchange rates'=>'تمكين أسعار الصرف التلقائية','Exchange rates source'=>'مصدر أسعار الصرف','Lifting charge'=>'رسوم تحويل','The lifting charge adjusts the exchange rate provided by the selected service before it is saved. The exchange rates displayed in the table above include the lifting charge.'=>'تقوم رسوم التحويل بتعديل سعر الصرف المقدم من الخدمة المختارة قبل حفظه. تشمل أسعار الصرف المعروضة في الجدول أعلاه رسوم التحويل.','Exchange rate = %s exchange rate x (1 + lifting charge / 100)'=>'سعر الصرف = سعر صرف %s × (1 + رسوم التحويل / 100)','API key (required)'=>'مفتاح API (مطلوب)','Update frequency'=>'تكرار التحديث','Update manually now'=>'تحديث يدوي الآن','You have to save all settings before updating exchange rates'=>'يجب عليك حفظ كافة الإعدادات قبل تحديث أسعار الصرف','Manually'=>'يدويًا','Hourly'=>'كل ساعة','Daily'=>'يوميًا','Weekly on'=>'أسبوعيًا في يوم','Monthly on the'=>'شهريًا في يوم','Enter API key'=>'أدخل مفتاح API','WARNING! Minor limitations include 1000 requests/month limit and EUR being the only available base currency for customers using a free account. If you need more than 1000 requests per month or want to use all 170 available base currencies, you’ll need to choose one of the paid plans starting at only $10 per month.'=>'تحذير! تشمل القيود البسيطة حد 1000 طلب/شهر وكون اليورو هو العملة الأساسية الوحيدة المتاحة للعملاء الذين يستخدمون حسابًا مجانيًا. إذا كنت بحاجة إلى أكثر من 1000 طلب شهريًا أو تريد استخدام جميع العملات الأساسية الـ 170 المتاحة، فستحتاج إلى اختيار إحدى الخطط المدفوعة التي تبدأ من $10 فقط شهريًا.','Updating the exchange rates on an hourly basis generates around 744 API calls a month. Please check that your exchange rates source can accommodate this higher usage.'=>'يؤدي تحديث أسعار الصرف على أساس كل ساعة إلى إنشاء حوالي 744 مكالمة API شهريًا. يرجى التحقق من أن مصدر أسعار الصرف الخاص بك يمكنه استيعاب هذا الاستخدام العالي.','Last updated: %s'=>'آخر تحديث: %s','Exchange rates updated successfully'=>'تم تحديث أسعار الصرف بنجاح','Visit website'=>'زيارة الموقع الإلكتروني','Enable/disable'=>'تمكين/تعطيل','The multi-currency mode cannot be enabled as a specific currency was not set. Go to the %1$sWooCommerce settings%2$s page and select the default currency for your store.'=>'لا يمكن تمكين وضع العملات المتعددة لأنه لم يتم تعيين عملة محددة. انتقل إلى صفحة %1$sإعدادات WooCommerce%2$s وحدد العملة الافتراضية لمتجرك.','Enable the multicurrency mode'=>'تمكين وضع العملات المتعددة','Multicurrency documentation'=>'وثائق العملات المتعددة','Custom prices'=>'أسعار مخصصة','Show only products with %1$scustom prices%2$s in secondary currencies'=>'إظهار المنتجات ذات %1$sالأسعار المخصصة%2$s فقط بالعملات الثانوية','When enabled, products with prices based on the exchange rate are hidden'=>'عند التمكين، يتم إخفاء المنتجات ذات الأسعار المستندة إلى سعر الصرف','The changes you made will be lost if you navigate away from this page.'=>'ستفقد التغييرات التي أجريتها إذا غادرت هذه الصفحة.','At least one currency must be enabled for this language!'=>'يجب تمكين عملة واحدة على الأقل لهذه اللغة!','Currency switcher options'=>'خيارات مبدل العملة','All currency switchers in your site are affected by the settings in this section.'=>'تتأثر جميع مبدلات العملات في موقعك بالإعدادات الموجودة في هذا القسم.','Order of currencies'=>'ترتيب العملات','Additional CSS'=>'CSS إضافي','Widget Currency Switcher'=>'ودجت مبدل العملة','Product page Currency Switcher'=>'مبدل العملة في صفحة المنتج','Position'=>'الموقع','Actions'=>'الإجراءات','Action'=>'الإجراء','Edit currency switcher'=>'تعديل مبدل العملة','Add a new currency switcher to a widget area'=>'إضافة مبدل عملة جديد إلى منطقة ودجت','Your theme does not support a currency switcher widget. Please %1$sadd your currency switcher%2$s using a shortcode or PHP.'=>'قالبك لا يدعم ودجت مبدل العملة. يرجى %1$sإضافة مبدل العملة الخاص بك%2$s باستخدام كود قصير أو PHP.','Currency switcher preview'=>'معاينة مبدل العملة','Drag and drop the currencies to change their order'=>'اسحب العملات وأفلتها لتغيير ترتيبها','Show a currency switcher on the product page template'=>'إظهار مبدل العملة في قالب صفحة المنتج','Edit Product Currency Switcher'=>'تعديل مبدل عملة المنتج','New Widget Area Currency Switcher'=>'مبدل عملة جديد لمنطقة الودجت','Edit %s Currency Switcher'=>'تعديل مبدل عملة %s','Which product attributes should be translatable?'=>'أي سمات المنتج يجب أن تكون قابلة للترجمة؟','WPML allows you to %1$stranslate your product attributes%2$s. Some attributes, like the ones based on numbers and codes, can be universal and might not need to be translated.'=>'يتيح لك WPML %1$sترجمة سمات منتجك%2$s. بعض السمات، مثل تلك القائمة على الأرقام والأكواد، يمكن أن تكون عالمية وقد لا تحتاج إلى ترجمة.','Select which attributes in your store should be translatable:'=>'حدد السمات في متجرك التي يجب أن تكون قابلة للترجمة:','There are no attributes defined'=>'لا توجد سمات محددة','Continue'=>'متابعة','Go back'=>'العودة','WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard'=>'WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard','Let\'s make your WooCommerce store multilingual'=>'دعنا نجعل متجر WooCommerce الخاص بك متعدد اللغات','To get started, we need to set up the following:'=>'للبدء، نحتاج إلى إعداد ما يلي:','Create store pages in all your site\'s languages'=>'إنشاء صفحات المتجر بجميع لغات موقعك','Choose which product attributes you want to translate'=>'اختر سمات المنتج التي تريد ترجمتها','Set your translation options'=>'ضبط خيارات الترجمة الخاصة بك','Decide if you want to add multiple currencies to your store'=>'قرر ما إذا كنت تريد إضافة عملات متعددة إلى متجرك','Let\'s continue'=>'دعنا نتابع','I\'ll do the setup later'=>'سأقوم بالإعداد لاحقًا','Do you want to add more currencies to your store?'=>'هل تريد إضافة المزيد من العملات إلى متجرك؟','You will be able to:'=>'ستكون قادرًا على:','Add a currency switcher to your store'=>'إضافة مبدل عملة إلى متجرك','Set exchange rates'=>'تعيين أسعار الصرف','Create custom pricing in each currency'=>'إنشاء تسعير مخصص بكل عملة','And more!'=>'والمزيد!','Yes, enable multicurrency mode'=>'نعم، قم بتمكين وضع العملات المتعددة','No, use only one currency'=>'لا، استخدم عملة واحدة فقط','Make your store multilingual'=>'اجعل متجرك متعدد اللغات','Set up %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s to translate your store and add more currencies.'=>'أعدّ %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s لترجمة متجرك وإضافة المزيد من العملات.','Start the Setup Wizard'=>'بدء Setup Wizard','Click continue to create missing WooCommerce pages translate your store pages into the following languages:'=>'انقر فوق متابعة لإنشاء صفحات WooCommerce المفقودة وترجمة صفحات متجرك إلى اللغات التالية:','Click continue to translate your store pages into the following languages:'=>'انقر فوق متابعة لترجمة صفحات متجرك إلى اللغات التالية:','WPML automatically generates translated versions of default WooCommerce pages, such as Shop, Account, Checkout, and Cart.'=>'يقوم WPML تلقائيًا بإنشاء نسخ مترجمة من صفحات WooCommerce الافتراضية، مثل المتجر، والحساب، وإتمام الطلب، وسلة المشتريات.','Configuration Warnings'=>'تحذيرات التكوين','Your product permalink base is not translated to:'=>'قاعدة الاسم اللطيف لمنتجك غير مترجمة إلى:','Translate URLs'=>'ترجمة عناوين URL','Running WPML Multilingual & Multicurrency for WooCommerce with default language other than English.'=>'تشغيل WPML Multilingual & Multicurrency for WooCommerce بلغة افتراضية غير الإنجليزية.','This may cause problems with URLs in different languages.'=>'قد يتسبب هذا في مشكلات في عناوين URL بلغات مختلفة.','Change default language'=>'تغيير اللغة الافتراضية','There are some settings that require careful attention.'=>'هناك بعض الإعدادات التي تتطلب اهتمامًا دقيقًا.','Some settings from the WPML Multilingual & Multicurrency for WooCommerce wpml-config.xml file have been overwritten.'=>'تم استبدال بعض الإعدادات من ملف wpml-config.xml الخاص بـ WPML Multilingual & Multicurrency for WooCommerce.','You should check WPML configuration files added by other plugins or manual settings on the %s section.'=>'يجب عليك التحقق من ملفات تكوين WPML المضافة بواسطة إضافات أخرى أو الإعدادات اليدوية في قسم %s.','Multilingual Content Setup'=>'إعداد المحتوى متعدد اللغات','Media'=>'الوسائط','%s is not active.'=>'%s غير نشط.','%s is not required in order to run WPML Multilingual & Multicurrency for WooCommerce but it’s recommended if you want to use separate product images and galleries for different languages.'=>'%s ليس مطلوبًا لتشغيل WPML Multilingual & Multicurrency for WooCommerce ولكنه موصى به إذا كنت تريد استخدام صور ومعارض منتجات منفصلة للغات مختلفة.','%s is installed and active.'=>'%s مثبت ونشط.','Secondary currencies: %s'=>'العملات الثانوية: %s','Multi-currency is not enabled.'=>'وضع العملات المتعددة غير مُمكّن.','Add Currencies'=>'إضافة عملات','Products Missing Translations'=>'منتجات مفقودة الترجمات','%1$d %2$s translation missing.'=>'ترجمة %2$s واحدة مفقودة لـ %1$d.','%1$d %2$s translations missing.'=>'هناك %1$d ترجمة مفقودة لـ %2$s.','Right now, there are no products needing translation.'=>'في الوقت الحالي، لا توجد منتجات تحتاج إلى ترجمة.','Plugins Status'=>'حالة الإضافات','%s is set up.'=>'تم إعداد %s.','%s is not set up.'=>'لم يتم إعداد %s.','WPML Multilingual & Multicurrency for WooCommerce depends on several plugins to work. If any required plugin is missing, you should install and activate it.'=>'يعتمد WPML Multilingual & Multicurrency for WooCommerce على عدة إضافات ليعمل. إذا كانت أي إضافة مطلوبة مفقودة، فيجب عليك تثبيتها وتفعيلها.','WooCommerce Store Pages'=>'صفحات متجر WooCommerce','To run a multilingual e-commerce site, you need to have the WooCommerce shop pages translated to all the site\'s languages. Once all the pages are installed you can add the translations for them from this menu.'=>'لتشغيل موقع تجارة إلكترونية متعدد اللغات، يجب أن تكون صفحات متجر WooCommerce مترجمة إلى جميع لغات الموقع. بمجرد تثبيت جميع الصفحات، يمكنك إضافة ترجمات لها من هذه القائمة.','One or more WooCommerce pages have not been created.'=>'لم يتم إنشاء صفحة واحدة أو أكثر من صفحات WooCommerce.','Install WooCommerce Pages'=>'تثبيت صفحات WooCommerce','WooCommerce store pages do not exist for these languages:'=>'صفحات متجر WooCommerce غير موجودة لهذه اللغات:','Create missing translations'=>'إنشاء الترجمات المفقودة','These pages are currently being translated by translators via WPML: '=>'تتم ترجمة هذه الصفحات حاليًا بواسطة المترجمين عبر WPML: ','WooCommerce store pages are translated to all the site\'s languages.'=>'تمت ترجمة صفحات متجر WooCommerce إلى جميع لغات الموقع.','Taxonomies Missing Translations'=>'تصنيفات مفقودة الترجمة','To run a fully translated site, you should translate all taxonomy terms. Some store elements, such as variations, depend on taxonomy translation.'=>'لتشغيل موقع مترجم بالكامل، يجب عليك ترجمة جميع مصطلحات التصنيفات. تعتمد بعض عناصر المتجر، مثل التنويعات، على ترجمة التصنيفات.','%s do not require translation.'=>'لا تتطلب %s ترجمة.','This taxonomy requires translation.'=>'يتطلب هذا التصنيف ترجمة.','%1$d %2$s is missing translations.'=>'تفتقد %1$d من مصطلحات %2$s إلى الترجمة.','%1$d %2$s are missing translations.'=>'تفتقد %1$d من مصطلحات %2$s إلى الترجمة.','Translate %s'=>'ترجمة %s','This taxonomy does not require translation.'=>'هذا التصنيف لا يتطلب ترجمة.','All %s are translated.'=>'تمت ترجمة جميع %s.','Right now, there are no taxonomy terms needing translation.'=>'في الوقت الحالي، لا توجد مصطلحات تصنيف تحتاج إلى ترجمة.','To configure product taxonomies or attributes as translatable or not translatable, go to the %1$sMultilingual Content Setup%2$s'=>'لتكوين تصنيفات المنتج أو سماته كقابلة للترجمة أو غير قابلة للترجمة، انتقل إلى %1$sإعداد المحتوى متعدد اللغات%2$s','Original'=>'الأصل','Translation to'=>'الترجمة إلى','Product Shop Base'=>'قاعدة متجر المنتج','Original language'=>'اللغة الأصلية','Update translation'=>'تحديث الترجمة','Add translation'=>'إضافة ترجمة','Edit translation'=>'تعديل الترجمة','This page allows you to translate all strings that are being used by WooCommerce in building different type of urls. Translating them enables you to have fully localized urls that match the language of the pages.'=>'تتيح لك هذه الصفحة ترجمة جميع النصوص التي يستخدمها WooCommerce في بناء أنواع مختلفة من عناوين URL. تتيح لك ترجمتها الحصول على عناوين URL معربة بالكامل تتوافق مع لغة الصفحات.','You can enter or edit your default values on the %1$sPermalinks settings%2$s page or, for the endpoints, on the WooCommerce %3$sAdvanced settings%4$s page.'=>'يمكنك إدخال قيمك الافتراضية أو تعديلها في صفحة %1$sإعدادات الروابط الدائمة%2$s أو، بالنسبة لنقاط النهاية، في صفحة WooCommerce %3$sالإعدادات المتقدمة%4$s.','permalinks settings'=>'إعدادات الروابط الدائمة','Account settings'=>'إعدادات الحساب','Slug type'=>'نوع الاسم اللطيف','Original Slug'=>'الاسم اللطيف الأصلي','Shop page'=>'صفحة المتجر','Product base'=>'قاعدة المنتج','Product category base'=>'قاعدة تصنيف المنتج','Product tag base'=>'قاعدة وسم المنتج','Product attribute base'=>'قاعدة سمة المنتج','Attribute slug: %s'=>'الاسم اللطيف للسمة: %s','Product'=>'منتج','Slug'=>'الاسم اللطيف','Content / Description'=>'المحتوى / الوصف','Excerpt'=>'مقتطف','Purchase note'=>'ملاحظة الشراء','Images'=>'الصور','Custom Product attributes'=>'سمات المنتج المخصصة','Value(s)'=>'القيمة (القيم)','Custom Fields'=>'حقول مخصصة','Variations data'=>'بيانات التنويعات','Download Files for Variation #%s'=>'تنزيل ملفات التنويع رقم %s','Download Files'=>'تنزيل الملفات','File URL'=>'عنوان URL للملف','External Product'=>'منتج خارجي','Product url'=>'عنوان URL للمنتج','Button text'=>'نص الزر','Changes in these translations will affect terms in general! ( Not only for this product )'=>'التغييرات في هذه الترجمات ستؤثر على المصطلحات بشكل عام! (ليس فقط لهذا المنتج)','Content, title, and excerpt are empty.'=>'المحتوى والعنوان والمقتطف فارغة.']];